const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: '由静止释放' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;

    function tw(i, dflt) {
      var it = (metrics && metrics[i]) || {};
      return typeof it.width === 'number' ? it.width : dflt;
    }

    var cx = W * 0.5;
    var R = Math.min(W, H) * 0.10;
    if (R > 30) { R = 30; }
    if (R < 12) { R = 12; }
    var cy = H * 0.22;

    var top = cy + R + H * 0.06;
    var bot = H * 0.80;
    if (bot - top < 60) { bot = top + 60; }
    if (bot > H - 12) { bot = H - 12; }
    if (bot <= top) { top = cy + R + 6; bot = top + 40; }

    var off = Math.max(R * 2.0, 36);
    if (cx - off < 20) { off = cx - 20; }
    if (off < 20) { off = 20; }
    var vx = cx - off;
    var gx = cx + off;

    var hl = 12;
    var hw = 7;
    var midY = (top + bot) / 2;

    var wv = tw(0, 8);
    var wg = tw(1, 9);
    var wt = tw(2, 66);

    var paths = [
      { id: 'ball', commands: visualSdk.circle(cx, cy, R) },
      { id: 'trace', commands: visualSdk.polyline([[cx, cy + R + 2], [cx, bot + 12]]) },
      { id: 'vShaft', commands: visualSdk.polyline([[vx, top], [vx, bot]]) },
      { id: 'vHead', commands: visualSdk.polyline([[vx - hw, bot - hl], [vx, bot], [vx + hw, bot - hl]]) },
      { id: 'gShaft', commands: visualSdk.polyline([[gx, top], [gx, bot]]) },
      { id: 'gHead', commands: visualSdk.polyline([[gx - hw, bot - hl], [gx, bot], [gx + hw, bot - hl]]) }
    ];

    var titleY = cy - R - 16;
    if (titleY < 14) { titleY = 14; }

    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'trace', stroke: '#9aa7b8' },
          { type: 'path', pathId: 'ball', stroke: '#26354a' },
          { type: 'path', pathId: 'vShaft', stroke: '#1a4d8f' },
          { type: 'path', pathId: 'vHead', stroke: '#1a4d8f' },
          { type: 'path', pathId: 'gShaft', stroke: '#a34a00' },
          { type: 'path', pathId: 'gHead', stroke: '#a34a00' },
          { type: 'label', text: 'v', x: vx - wv - 8, y: midY },
          { type: 'label', text: 'g', x: gx + 8, y: midY },
          { type: 'label', text: '由静止释放', x: cx - wt / 2, y: titleY }
        ]
      }
    };
  }
};
